def rotate_share(path, *, share_id, rotation_id):
    now = _utc_iso(datetime.now(timezone.utc))
    token = None
    with closing(sqlite3.connect(path)) as connection:
        connection.row_factory = sqlite3.Row
        connection.isolation_level = None
        connection.execute("BEGIN IMMEDIATE")
        try:
            share = connection.execute(
                "SELECT * FROM shares WHERE share_id = ?", (share_id,)
            ).fetchone()
            if share is None:
                connection.execute("COMMIT")
                return None
            existing = connection.execute(
                "SELECT * FROM share_rotations WHERE share_id = ? AND rotation_id = ?",
                (share_id, rotation_id),
            ).fetchone()
            if existing is not None:
                connection.execute("COMMIT")
                return _rotation_from_row(existing), False
            if share["revoked_at"] is not None or share["expires_at"] <= now:
                raise ShareRotationConflictError(share_id)
            token = secrets.token_urlsafe(32)
            version = share["token_version"] + 1
            record = {
                "share_id": share_id,
                "rotation_id": rotation_id,
                "token": token,
                "token_version": version,
                "rotated_at": now,
            }
            connection.execute(
                "INSERT INTO share_rotations (share_id, rotation_id, token_digest, token_version, rotated_at) VALUES (?, ?, ?, ?, ?)",
                (share_id, rotation_id, hash_token(token), version, now),
            )
            connection.execute(
                "UPDATE shares SET token_digest = ?, token_version = ? WHERE share_id = ?",
                (hash_token(token), version, share_id),
            )
            connection.execute("COMMIT")
            return record, True
        except BaseException:
            if connection.in_transaction:
                connection.execute("ROLLBACK")
            raise
